const input = $input.first();
const data = input.json ?? {};
const binary = input.binary ?? {};
const title = String(data.procurement_title ?? '').trim();
const number = String(data.procurement_number ?? '').trim();
const comment = String(data.comment ?? '').trim();
const files = Object.entries(binary);
const SUPPORTED_DOCUMENTS = new Set(['pdf', 'docx', 'xlsx', 'xls', 'txt', 'csv', 'tsv', 'md', 'json', 'xml', 'html', 'rtf', 'png', 'jpg', 'jpeg', 'tif', 'tiff', 'bmp', 'webp']);
const SUPPORTED_ARCHIVES = new Set(['zip', '7z', 'rar', 'tar', 'gz', 'tar.gz', 'tgz']);

function extensionOf(fileName) {
  const lower = String(fileName ?? '').trim().toLowerCase();
  if (lower.endsWith('.tar.gz')) return 'tar.gz';
  const dot = lower.lastIndexOf('.');
  return dot > 0 ? lower.slice(dot + 1) : '';
}

if (!title) throw new Error('[Manual Upload] procurement_title is required.');
if (title.length > 500 || number.length > 200 || comment.length > 2000) {
  throw new Error('[Manual Upload] Text field is too long.');
}
if (files.length < 1) throw new Error('[Manual Upload] At least one document is required.');
if (files.length > 100) throw new Error('[Manual Upload] No more than 100 source files are allowed.');

const fileMetadata = files.map(([binaryKey, descriptor], offset) => {
  const fileName = String(descriptor?.fileName ?? '').normalize('NFC').trim();
  if (!fileName || fileName.length > 200 || /[\/�-]/u.test(fileName)) {
    throw new Error('[Manual Upload] Unsafe file name.');
  }
  const extension = extensionOf(fileName);
  if (!SUPPORTED_DOCUMENTS.has(extension) && !SUPPORTED_ARCHIVES.has(extension)) {
    throw new Error('[Manual Upload] Executable or unsupported file type: ' + fileName);
  }
  return {
    binary_key: binaryKey,
    document_index: offset + 1,
    file_name: fileName,
    file_extension: extension,
    mime_type: String(descriptor?.mimeType ?? 'application/octet-stream').slice(0, 200),
  };
});

return [{
  json: {
    procurement_title: title,
    procurement_number: number || null,
    comment: comment || null,
    submitted_at: data.submittedAt ?? null,
    form_mode: data.formMode ?? null,
    file_metadata: fileMetadata,
  },
  binary,
}];

const generated = $input.first().json ?? {};
const source = $('Проверить ручную загрузку').first();
const context = source.json;
const analysisRunId = String(generated.analysis_run_id ?? generated.data ?? '').trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu.test(analysisRunId)) {
  throw new Error('[Manual Upload] Generated analysis_run_id is invalid.');
}
return context.file_metadata.map((file) => ({
  json: {
    analysis_run_id: analysisRunId,
    upload_job_id: analysisRunId + '--upload-' + String(file.document_index).padStart(6, '0'),
    procurement_title: context.procurement_title,
    procurement_number: context.procurement_number,
    comment: context.comment,
    submitted_at: context.submitted_at,
    form_mode: context.form_mode,
    ...file,
  },
  binary: { data: source.binary[file.binary_key] },
}));

const rows = $input.all().map((item) => item.json).sort((a, b) => a.uploaded_source.document_index - b.uploaded_source.document_index);
if (rows.length < 1) throw new Error('[Manual Upload] No stored source files were returned.');
const first = rows[0];
if (rows.some((row) => row.analysis_run_id !== first.analysis_run_id)) {
  throw new Error('[Manual Upload] Mixed analysis_run_id values.');
}
const attachments = rows.map((row) => row.uploaded_source);
const totalBytes = attachments.reduce((sum, file) => sum + Number(file.source_size ?? 0), 0);
if (!Number.isSafeInteger(totalBytes) || totalBytes < 0) {
  throw new Error('[Manual Upload] Uploaded byte total is invalid.');
}
if (totalBytes > 200 * 1024 * 1024) {
  throw new Error('[MANUAL_UPLOAD_TOTAL_TOO_LARGE] Total upload exceeds 200 MiB.');
}
const tenderId = 'manual:' + first.analysis_run_id;
return [{ json: {
  analysis_run_id: first.analysis_run_id,
  source: 'manual_upload',
  tender_meta: {
    source: 'manual_upload',
    tender_id: tenderId,
    tender_number: first.procurement_number,
    tender_external_id: null,
    title: first.procurement_title,
    documents_count: attachments.length,
    source_payload: {
      procurement_title: first.procurement_title,
      procurement_number: first.procurement_number,
      comment: first.comment,
      submitted_at: first.submitted_at,
      form_mode: first.form_mode,
      n8n_execution_id: String($execution.id),
      files: attachments.map((file) => ({
        document_index: file.document_index,
        file_name: file.file_name,
        file_extension: file.file_extension,
        source_size: file.source_size,
        sha256: file.sha256,
      })),
    },
  },
  attachments,
  total_upload_bytes: totalBytes,
} }];

const result = $input.first().json;
const context = $('Собрать сохранённые исходники').first().json;
if (result.success !== true || result.schema_version !== 'tender_document_ingestion_v1' || !result.manifest) {
  throw new Error('[Manual Upload] Document preparation failed: ' + String(result.failure?.error_code ?? 'UNKNOWN'));
}
if (result.analysis_run_id !== context.analysis_run_id || result.manifest.analysis_run_id !== context.analysis_run_id) {
  throw new Error('[Manual Upload] Preparation identity mismatch.');
}
const documents = Array.isArray(result.manifest.documents) ? result.manifest.documents : [];
if (documents.length < 1 || Number(result.manifest.processable_document_count) < 1) {
  throw new Error('[Manual Upload] Preparation returned no processable documents.');
}
return [{ json: {
  analysis_run_id: context.analysis_run_id,
  source: 'manual_upload',
  tender_meta: context.tender_meta,
  attachments: documents,
  manifest: result.manifest,
} }];

const row = $input.first().json;
const expected = $('Проверить результат подготовки').first().json.attachments.length;
if (row.created_new_run !== true || !row.analysis_run_id) {
  throw new Error('[Manual Upload] Analysis run was not created.');
}
if (Number(row.documents_total) !== expected || Number(row.registered_documents_count) !== expected) {
  throw new Error('[Manual Upload] Not all prepared documents were registered.');
}
return [{ json: {
  analysis_run_id: String(row.analysis_run_id),
  source: 'manual_upload',
  tender_id: String(row.tender_id),
  documents_total: expected,
} }];

const result = $input.first().json;
const run = $('Проверить регистрацию запуска').first().json;
if (result.schema_version !== 'tender_agentic_dispatch_v1' || result.success === false) {
  throw new Error('[Manual Upload] Agentic dispatch failed.');
}
return [{ json: {
  success: true,
  analysis_run_id: run.analysis_run_id,
  tender_id: run.tender_id,
  documents_total: run.documents_total,
  agent_status: result.status ?? null,
  job_id: result.job_id ?? null,
} }];

const response = $json;
const source = $('Загрузить файлы по одному').item.json;
if (response.schema_version !== 'tender_manual_source_upload_v1' || response.success !== true) {
  throw new Error('[Manual Upload] Source storage returned an invalid contract.');
}
if (response.analysis_run_id !== source.analysis_run_id || Number(response.source_attachment_index) !== source.document_index) {
  throw new Error('[Manual Upload] Source storage identity mismatch.');
}
const entry = Array.isArray(response.entries) ? response.entries[0] : null;
if (!entry || response.entries.length !== 1 || !entry.download_url || !/^[0-9a-f]{64}$/u.test(String(entry.sha256 ?? ''))) {
  throw new Error('[Manual Upload] Stored source metadata is incomplete.');
}
return {
  json: {
    analysis_run_id: source.analysis_run_id,
    procurement_title: source.procurement_title,
    procurement_number: source.procurement_number,
    comment: source.comment,
    submitted_at: source.submitted_at,
    form_mode: source.form_mode,
    uploaded_source: {
      document_index: source.document_index,
      file_name: source.file_name,
      file_extension: source.file_extension,
      display_name: source.file_name,
      download_url: String(entry.download_url),
      publication_at: null,
      source_size: Number(entry.size_bytes),
      mime_type: String(entry.mime_type ?? source.mime_type),
      sha256: String(entry.sha256).toLowerCase(),
    },
  },
};
